source.loginCheckJs:
(function(){
  try {
    /* 未登录访问「我的求书」时站点 302 → /auth/login.php，
       因此判据是：最终 URL 是登录页（而不是原来写的 /user/requests.php，
       那个 URL 在重定向后永远不会出现，提示从来不会弹）。 */
    var u = String(result.url() || '');
    if (u.indexOf('/auth/login.php') >= 0) {
      java.toast('⚠️ 查看「我的求书」需要先登录：书源管理 → 本来源 → 登录');
    }
  } catch (e) {}
  return result;
})()

source.loginUrl:
function zsHomeHtml(){
    try { return String(java.ajax('https://www.zhaoshu.la/')); } catch(e) { return ''; }
}
function zsLogged(html){
    // 判据：页头「退出登录 /auth/logout.php」链接只在已登录时渲染。
    // 不能用 /request/create.php —— 首页导航栏常年挂这个入口占位；
    // 也不能用「登录你的找书啦账号」反向判断 —— 这句是登录框副标题，登录页必含。
    return String(html).indexOf('/auth/logout.php') >= 0;
}
function zsFlashMsg(html){
    var m = String(html).match(/--danger-bg[^>]*>([\s\S]*?)<\/div>/);
    if (!m) return '';
    return String(m[1]).replace(/<[^>]+>/g, '').replace(/\s+/g, '');
}
/* 取指定页面的 csrf_token。页面自身渲染失败/被WAF时才返回空串；
   旧版曾把「登录你的找书啦账号」当未登录哨兵——实际上它是登录框副标题，
   登录页本身就含这句话，导致 token 永远被清空（260907 修复）。 */
function zsCsrf(path){
    var h = '';
    try { h = String(java.ajax('https://www.zhaoshu.la' + path)); } catch(e) { return ''; }
    var m = h.match(/name="csrf_token" value="([0-9a-f]+)"/);
    return m ? m[1] : '';
}
function zsToken(){ return zsCsrf('/auth/login.php'); }
/* 表单 POST，走 java.ajax 的 URL 选项式以复用 CookieJar 与书源 UA */
function zsPost(path, formObj){
    var pairs = [];
    for (var k in formObj) pairs.push(encodeURIComponent(k) + '=' + encodeURIComponent(formObj[k]));
    var opt = { method: 'POST', body: pairs.join('&'),
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' } };
    return String(java.ajax('https://www.zhaoshu.la' + path + ',' + JSON.stringify(opt)));
}
function zsGet(path){
    try { return String(java.ajax('https://www.zhaoshu.la' + path)); } catch(e) { return ''; }
}
/* 站点对「未登录时的POST」一律 302 → 首页（登录成功也 302 → 首页），
   POST 响应体被重定向吞掉 flash（如"邮箱或密码错误"）。
   会话是否有效用 GET 首页看「退出登录」链接复核。 */
function zsSessionValid(){
    return zsLogged(zsHomeHtml());
}
function login(){
    var em = '', pw = '';
    try {
        em = String(result.get('邮箱') || '').trim();
        pw = String(result.get('密码') || '');
    } catch (e) { em = ''; pw = ''; }
    if (!em || !pw) { java.toast('⚠️ 请先填写邮箱和密码'); return; }
    java.toast('⏳ 正在登录找书啦…');
    try {
        var tk = zsToken();
        if (!tk) { java.toast('❌ 未取得CSRF令牌，站点可能触发WAF，请稍后再试'); return; }
        var res = zsPost('/auth/login.php', { csrf_token: tk, email: em, password: pw });
        if (res.indexOf('GOEDGE_WAF') >= 0) {
            java.toast('❌ 触发WAF人机验证，请先用浏览器打开网站过一次验证');
            return;
        }
        /* 会话复核：登录成败不能只看 POST 响应（可能被 302 重定向改写），
           重新 GET 首页看「退出登录」链接是否出现 */
        if (zsSessionValid()) {
            java.toast('✅ 登录成功：' + em + '　现在可以发布求书帖了');
        } else {
            var fm = zsFlashMsg(res);
            if (!fm) {
                /* flash 可能被 302 吞掉，补一发登录页 GET 兜底 */
                fm = zsFlashMsg(String(java.ajax('https://www.zhaoshu.la/auth/login.php')));
            }
            java.toast('❌ 登录失败：' + (fm || '邮箱或密码不正确'));
        }
    } catch (e2) {
        java.toast('❌ 登录异常：' + e2.message);
    }
}
/* 发布求书帖：POST /request/create.php  csrf_token + book_name + description */
function publishRequest(){
    var nm = '', ds = '';
    try {
        nm = String(result.get('书名') || '').trim();
        ds = String(result.get('描述') || '').trim();
    } catch (e) { nm = ''; ds = ''; }
    if (!nm || nm.length < 2)  { java.toast('⚠️ 书名至少 2 个字'); return; }
    if (nm.length > 200)       { java.toast('⚠️ 书名不能超过 200 字'); return; }
    if (!ds || ds.length < 10) { java.toast('⚠️ 描述至少 10 个字，线索越详细越容易被找到'); return; }
    java.toast('⏳ 正在发布求书帖…');
    try {
        /* 260907实测：已登录但处于发帖限制时，create.php 会静默 302 回首页（无表单无提示），
           必须先判页面形态再决定提示，否则会把"限制中"误报成"未登录" */
        var cp = zsGet('/request/create.php');
        if (cp.indexOf('name="book_name"') < 0) {
            if (zsLogged(cp)) {
                java.toast('❌ 站点暂不接受发布：可能处于发帖冷却期（发帖后一段时间内不能再发）或账号受限，请稍后再试');
            } else {
                java.toast('❌ 未登录无法发布：请先填邮箱密码点「① 登录」');
            }
            return;
        }
        var tk = (cp.match(/name="csrf_token" value="([0-9a-f]+)"/) || [])[1] || '';
        if (!tk) { java.toast('❌ 未取得CSRF令牌，请稍后再试'); return; }
        if (!zsSessionValid()) { java.toast('❌ 登录已失效，请重新点「① 登录」'); return; }
        var res = zsPost('/request/create.php', { csrf_token: tk, book_name: nm, description: ds });
        if (res.indexOf('GOEDGE_WAF') >= 0) {
            java.toast('❌ 触发WAF人机验证，请先用浏览器打开网站过一次验证');
            return;
        }
        var cid = res.match(/canonical" href="https?:\/\/[^\/]+\/request\/(\d+)\.html"/);
        if (res.indexOf('发布成功') >= 0 || (cid && res.indexOf('request-book-name') >= 0)) {
            java.longToast('✅ 发布成功' + (cid ? ('：求书帖 #' + cid[1] + '《' + nm + '》') : '')
                + '\n可在发现页「🙋 我的求书」查看。'
                + '\n注意：站点不提供删除功能，帖子会长期公开。');
        } else {
            java.toast('❌ 发布失败：' + (zsFlashMsg(res) || '请确认已登录且描述不少于10字'));
        }
    } catch (e3) {
        java.toast('❌ 发布异常：' + e3.message);
    }
}
function openMyRequests(){
    java.toast('🙋 我的求书：回到书源「发现」页，点最后一个分类「🙋 我的求书」即可');
}
function checkLogin(){
    java.toast('⏳ 正在检查登录状态…');
    var h = zsHomeHtml();
    if (!h) { java.toast('❌ 无法访问网站，请检查网络'); return; }
    if (h.indexOf('GOEDGE_WAF') >= 0) { java.toast('❌ 触发WAF人机验证，请稍后重试'); return; }
    if (zsLogged(h)) {
        var m = h.match(/user-name">([^<]+)</);
        var n = h.match(/user-title[^>]*>([^<]*)</);
        java.toast('✅ 已登录：' + (m ? m[1] : '未知用户') + (n ? '（' + n[1].trim() + '）' : '') + '　可发布/回复求书帖');
    } else {
        java.toast('⚠️ 未登录（浏览找书无需登录，发帖/回复才需要）');
    }
}
function logout(){
    try {
        try { source.removeLoginInfo(); } catch(e0) {}
        cookie.removeCookie('https://www.zhaoshu.la/');
        try { source.removeLoginHeader(); } catch(e1) {}
        var still = zsLogged(zsHomeHtml());
        java.toast(still ? '⚠️ 已清除本站Cookie，但站点仍判定为登录中，重启阅读后生效'
                         : '🚪 已退出登录（本站Cookie已清除）');
    } catch (e) { java.toast('❌ 退出失败：' + e.message); }
}
function showHelp(){
    var t = '【找书啦 使用说明】' + String.fromCharCode(10)
          + '1. 发现页：最新已解决 / 最新未解决 / 全部求书 / 我的求书' + String.fromCharCode(10)
          + '2. 搜索框输入书名，匹配的是求书帖标题与描述' + String.fromCharCode(10)
          + '3. 点书名进详情页，书友回复里带网址即为找到的书源' + String.fromCharCode(10)
          + '4. 详情页简介是网页渲染的，直接点橙色「📖 打开这本书」按钮即可调起该书详情页' + String.fromCharCode(10)
          + '5. 目录里每条网址也会生成「🔗 一键开书」章节，作为按钮之外的双保险' + String.fromCharCode(10)
          + '6. 发布求书：先点「① 登录」，再填「书名」「描述」两点，点「④ 发布求书帖」' + String.fromCharCode(10)
          + '   书名字数 2~200，描述至少 10 字；站点无删除功能，请谨慎发布' + String.fromCharCode(10)
          + '7. 发布后点「发现 → 🙋 我的求书」查看自己的帖子（未登录时该页为空）' + String.fromCharCode(10)
          + '8. 浏览找书无需登录；只有发帖/回复才需要登录' + String.fromCharCode(10)
          + '9. 本站必须使用手机UA，电脑UA会触发GoEdge WAF人机验证';
    try { java.longToast(t); } catch (e) { try { java.toast(t); } catch (e2) { java.copyText(t); } }
}

