ruleToc.chapterList:
class.BCsectionTwo-top-chapter@js:(function(){
        // 方式一配置：可扩展的data属性数组
        var orderAttrs = ['data-x', 'data-nmb', 'data-tmd'];

        // 方式二：尝试获取originalOrder
        var originalOrder = null;
        try {
            var odMatch = src.match(/originalOrder\s*=\s*(\[.+?\])/);
            if(odMatch) {
                originalOrder = JSON.parse(odMatch[1]);
            }
        } catch(e) {}

        // 统一处理元素（已在外部通过CSS选择器获取到result）
        var chapters = [];
        for(var i=0;i<result.size();i++){
            var li = result.get(i);
            var aTag = li.select('a').first();
            if(aTag == null) continue;

            // 优先使用originalOrder方式
            var orderValue = i; // 默认保持原序
            if(originalOrder){
                orderValue = originalOrder[i]+1; // 原逻辑+1处理
            } 
            // 没有originalOrder时使用data属性方式
            else {
                for(var j=0;j<orderAttrs.length;j++){
                    var attrVal = li.attr(orderAttrs[j]);
                    if(attrVal && /^\d+$/.test(attrVal)){
                        orderValue = parseInt(attrVal);
                        break;
                    }
                }
            }

            chapters.push({
                element: aTag,
                order: orderValue,
                index: i
            });
        }

        // 执行排序
        chapters.sort(function(a,b){
            return a.order - b.order;
        });

        // 构建最终结果（只要<a>标签）
        var sortedResult = new Packages.java.util.ArrayList();
        for(var k=0;k<chapters.length;k++){
      sortedResult.add(chapters[k].element);
        }
        return sortedResult;
    })()

ruleToc.chapterUrl:
data-sb||data-link||data-dsb||data-idu||data-url||href
@js:(function(){
    // 判断是否需要解码（检测是否是base64编码的特征）
    if(result && /^[A-Za-z0-9+/]+={0,2}$/.test(result) && result.length % 4 === 0){
        try {
            var decoded = java.base64Decode(result);
            return decoded;
        } catch(e) {
            return result;
        }
    }
    // 非base64数据直接返回
    return result;
})()

