@js:
try {
    let cid = java.hexDecodeToString(result);

    eval(String(java.base64Decode(az)))

    function getComic(a){let r=a.match(/<article>([\s\S]*?)<\/article>/);try{let t=JSON.parse(r?r[1].replace(/\&/g,'"').replace(/\;/g,"").replace(/\#34/g,""):a);return(r?t.skeleton.data:t.picInfos).map(e=>{return`<img src="https://p3-novel.byteimg.com/origin/${r?t.materials[e.element_name].data.web_uri:"novel-pic/"+e.md5}">`}).join("<br>")}catch(e){return((r=a.match(/<body>([\s\S]*?)<\/body>/))?r[1]:a).toString().replace(/\<\!DOCTYPE html.*/g,"").replace(/\<tt_keyword_ad.*\<\/tt_keyword_ad\>/,"").replace(/\<a epub.*\>\<\/a\>/g,"")}}

    result = getComic(String(res));
    result = result.replace(/\{\!\-\- PGC_VOICE\:.*\-\-\}/g, "");
} catch (e) {
    try {
        result = JSON.parse(result).data[0]['main_url'];
    } catch (d) {
        result = "未知错误" + e + d;
    }
}

