ruleToc.chapterList:
@js:
type = java.get('btype')
if (type == 1) {
  book.type = 64;
} else if (type == 4) {
  book.type = 32;
} else {
  book.type = 8;
}

let list = []

function b64Url(item_id) {

	itemid = book.type==32?`https://reading.snssdk.com/reading/reader/audio/playinfo/?tone_id=1&item_ids=${item_id}&pv_player=-1&aid=1967`:`data:;base64,${java.base64Encode(item_id)},{"type":"pyfqc"}`; 
	return String(itemid);
}

let List = JSON.parse(result).data.chapterListWithVolume;
   for (let $ of List) {
        $.map((_, i) => {
        let name = _.volume_name || "第一卷：默认";
        let time = java.timeFormat(_.firstPassTime * 1000);
       if (!i && book.type!=32) list.push({title:name, vo:true});
       list.push({title:_.title, vo:false, itemid:b64Url(_.itemId), info:[name, time].join(" | ")})
              });
       }
list;

